css:
body{--k-accent:#00846C;--k-accent-dark:#005E4D;--k-soft:#E4F1EC;--k-ink:#13252B;--k-muted:#56676E;--k-line:#D5DDDF;--k-bg:#F1F4F4;--k-panel:#fff;--k-radius:6px;--k-shadow:none;--sb-before:#AAB6BC;--sb-now:#00846C;--sb-ask:#B86E0B;--sb-ask-soft:#FBF1E3}
#stage,.print-stage{font-family:"Malgun Gothic","Apple SD Gothic Neo","Noto Sans KR",sans-serif}
#stage.composed-scene,.print-stage.composed-scene{padding:34px 60px 30px;gap:14px}
.composed-scene .scene-title{font-size:42px;font-weight:800;letter-spacing:-.035em}
.composed-scene .eyebrow{font-size:16px;letter-spacing:0;color:var(--k-accent)}
.lead.summary{font-size:18px;background:#fff;border-left:5px solid var(--sb-now);font-variant-numeric:tabular-nums}
.message-label{border-radius:4px}
.sb-svg{width:100%;height:auto;display:block;overflow:visible}
.sb-svg text{font-family:inherit}
.sb-card{background:#fff;border:1px solid var(--k-line);border-radius:6px;padding:16px 22px;display:flex;flex-direction:column;gap:8px;min-height:0;min-width:0}
.sb-h{display:flex;align-items:baseline;gap:10px;font-size:18px;font-weight:800;margin:0;color:var(--k-ink)}
.sb-h small{font-size:13px;font-weight:500;color:var(--k-muted)}
.sb-note{font-size:14px;color:var(--k-muted);margin:0;line-height:1.5}
.sb-row{display:flex;align-items:center;justify-content:space-between;gap:16px}
.sb-go{border:1px solid var(--k-line);background:#fff;border-radius:4px;padding:6px 12px;font-size:14px;color:var(--k-ink);white-space:nowrap}
.sb-go:hover{border-color:var(--sb-now);color:var(--sb-now)}
.sb-notice{font-size:13px;color:var(--k-muted);margin:0}
.sb-axis{stroke:#8C9AA0;stroke-width:1.5}
.sb-grid{stroke:#E3E8E9;stroke-width:1}
.sb-track{stroke:#E3E8E9;stroke-width:6;stroke-linecap:round}
.sb-link{stroke:#9FCFC4;stroke-width:6;stroke-linecap:round}
.sb-target{stroke:var(--k-ink);stroke-width:2;stroke-dasharray:6 5}
.sb-ref{stroke:#9AA7AD;stroke-width:1.5;stroke-dasharray:3 5}
.b-before{fill:var(--sb-before)}.b-now{fill:var(--sb-now)}.b-goal{fill:#fff;stroke:var(--sb-now);stroke-width:2.5;stroke-dasharray:7 5}
.t-ax{font-size:13px;fill:#56676E}
.t-lab{font-size:16px;font-weight:700;fill:#13252B}
.t-sm{font-size:14px;fill:#56676E;font-variant-numeric:tabular-nums}
.t-sm-b{font-size:15px;font-weight:800;fill:#005E4D;font-variant-numeric:tabular-nums}
.t-val{font-size:20px;font-weight:800;fill:#13252B;font-variant-numeric:tabular-nums}
.t-big{font-size:30px;font-weight:800;fill:#13252B;font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.t-gain{font-size:20px;font-weight:800;fill:#005E4D}
.t-white{fill:#fff!important}
.t-hero{font-size:44px;font-weight:800;fill:#13252B;letter-spacing:-.02em}
.t-lab-l{font-size:20px;font-weight:800;fill:#13252B}
.deck-mark i{background:var(--sb-now)!important}
.sb-tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.sb-tile{background:var(--k-bg);border-radius:4px;padding:10px 14px;display:grid;grid-template-columns:1fr auto;row-gap:2px}
.sb-tile span{font-size:14px;color:var(--k-muted)}
.sb-tile b{grid-row:2;font-size:19px;font-variant-numeric:tabular-nums}
.sb-tile em{grid-row:1 / span 2;grid-column:2;align-self:center;font-style:normal;font-size:22px;font-weight:800;color:#005E4D}
.t-seg{font-size:15px;font-weight:700;fill:#13252B}.t-seg-v{font-size:17px;font-weight:800;fill:#13252B}

[data-scene="cover"] .scene-title{font-size:60px;max-width:1300px;margin-top:6px}
.sb-cover{display:flex;flex-direction:column;justify-content:space-between;height:100%;gap:10px}
.sb-cover-meta{font-size:20px;color:var(--k-muted);margin:0}
.sb-cover-rule{flex:1;display:flex;align-items:center}
.sb-cover-foot{display:flex;justify-content:space-between;align-items:flex-end;border-top:1px solid var(--k-line);padding-top:12px}
.sb-cover-order{margin:0;font-size:17px}.sb-cover-order b{margin-right:14px;color:var(--sb-now)}

.sb-sum{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,1fr);grid-template-rows:auto auto auto;gap:14px;flex:1;min-height:0}
.sb-sum-main{grid-row:1 / span 3;justify-content:space-between}
.sb-sum>.sb-card:not(.sb-sum-main){padding:12px 20px;gap:4px}
.sb-sum .sb-ask-card{gap:8px}
.sb-ask-card{background:var(--sb-ask-soft);border-color:#E7C590}
.sb-ask-card .sb-h{color:#7A4806}
.sb-ask-line{font-size:19px;margin:0}.sb-ask-line b{color:#8A5207;font-size:22px}
.sb-ask-card .sb-go{align-self:flex-start}

.sb-bg{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:16px;flex:1;min-height:0}
.sb-dots{max-height:420px}
.dot-wait{fill:var(--k-ink)}.dot-other{fill:#D5DDDF}
.sb-legend{display:flex;gap:26px;font-size:15px}
.sb-legend i{display:inline-block;width:13px;height:13px;border-radius:3px;margin-right:7px;vertical-align:-1px}
.sw-wait{background:var(--k-ink)}.sw-other{background:#D5DDDF}
.sb-bg-side{display:grid;grid-template-rows:repeat(3,minmax(0,1fr));gap:14px;min-height:0}
.sb-big{font-size:52px;font-weight:800;letter-spacing:-.03em;margin:0;line-height:1;font-variant-numeric:tabular-nums}
.sb-big span{font-size:22px;font-weight:700;margin-left:6px;color:var(--k-muted)}
.sb-goal .sb-big{color:var(--sb-now)}
.sb-chain{display:flex;align-items:center;gap:0;font-size:17px;font-weight:700}
.sb-chain span{padding:10px 14px;background:var(--k-bg);border-radius:4px}
.sb-chain span+span::before{content:"→";margin:0 10px 0 -4px;color:var(--k-muted);font-weight:400}

.sb-stage{display:grid;grid-template-rows:auto minmax(0,1fr);gap:14px;flex:1;min-height:0}
.sb-stage-low{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:14px;min-height:0}
.sb-table{font-size:16px}
.sb-stage .sb-table td,.sb-stage .sb-table th{padding-top:6px;padding-bottom:6px}
svg [data-step].focus{filter:none!important}
.soft-note p{font-size:17px;line-height:1.6;margin:0}
.sb-plane{fill:#00846C;opacity:.10}

.sb-acts{display:grid;grid-template-rows:minmax(0,1fr) auto;gap:14px;flex:1;min-height:0}
.sb-acts-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;min-height:0}
.sb-act{gap:12px;justify-content:space-between;position:relative}
.sb-act-stage{margin:0;font-size:16px;font-weight:700;color:var(--sb-now);display:flex;align-items:center;gap:10px}
.sb-act-stage b{width:28px;height:28px;border-radius:50%;background:var(--sb-now);color:#fff;display:grid;place-items:center;font-size:14px}
.sb-act-name{font-size:25px;margin:0;letter-spacing:-.02em;word-break:keep-all}
.sb-act-money{display:flex;flex-direction:column;gap:8px}
.sb-act-won{font-size:40px;font-weight:800;font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.sb-act-won small{font-size:17px;margin-left:5px;color:var(--k-muted)}
.sb-bar{display:block;height:14px;background:#EDF1F2;border-radius:2px}
.sb-bar i{display:block;height:100%;background:var(--sb-now);border-radius:2px}
.sb-act-wait{margin:0;font-size:16px;color:var(--k-muted);border-top:1px solid var(--k-line);padding-top:12px}
.sb-act-wait b{color:var(--k-ink)}
.sb-act:not(:last-child)::after{content:"";position:absolute;right:-12px;top:50%;width:10px;height:10px;border-top:2px solid #9AA7AD;border-right:2px solid #9AA7AD;transform:translateY(-50%) rotate(45deg)}
.sb-tl-row{display:grid;grid-template-columns:repeat(3,1fr);position:relative}
.sb-tl-item{font-size:16px;padding:10px 0 2px 22px;position:relative;border-top:3px solid #D5DDDF}
.sb-tl-item::before{content:"";position:absolute;left:0;top:-9px;width:14px;height:14px;border-radius:50%;background:#fff;border:3px solid #9AA7AD}
.sb-tl-item b{display:block;font-size:18px}
.sb-tl-item.now::before{border-color:var(--sb-now);background:var(--sb-now)}
.sb-tl-item.now b{color:var(--sb-now)}

.sb-trend{display:grid;grid-template-rows:minmax(0,1fr) auto;gap:14px;flex:1;min-height:0}
.sb-trend-chart{justify-content:center}
.sb-band{fill:#00846C;opacity:.07}.sb-band2{fill:#00846C;opacity:.035}
.sb-line{fill:none;stroke:var(--sb-now);stroke-width:4;stroke-linecap:round;stroke-linejoin:round}
.sb-pt{fill:#fff;stroke:var(--sb-now);stroke-width:4}
.sb-trend-notes{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.sb-trend-notes p{margin:0;background:#fff;border:1px solid var(--k-line);border-radius:6px;padding:12px 18px;font-size:17px}
.sb-trend-notes b{display:block;font-size:15px;color:var(--sb-now)}

.sb-sat{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:14px;flex:1;min-height:0}
.sb-slope{stroke:var(--sb-now);stroke-width:4}.sb-slope.thin{stroke-width:2.5;stroke-dasharray:8 5}
.sb-sat .sb-svg{max-height:470px}
.sb-sat-delta{font-size:30px;font-weight:800;color:#005E4D;margin:0}

.sb-rem{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) minmax(0,1.2fr);gap:14px;flex:1;min-height:0}
.sb-use{align-items:flex-start;justify-content:center}
.sb-waffle{max-width:270px}
.sb-cell.off{fill:#EDF1F2}.on-now{fill:var(--sb-now)}.on-ask{fill:var(--sb-ask)}
.sb-use-pct{font-size:58px;font-weight:800;margin:6px 0 0;line-height:1;letter-spacing:-.03em}
.sb-use-pct span{font-size:26px}
.sb-older .sb-use-pct{color:var(--sb-ask)}
.sb-use-name{margin:0;font-size:17px;font-weight:700;word-break:keep-all}
.sb-issue{background:var(--sb-ask-soft);border-color:#E7C590;justify-content:center;gap:16px}
.sb-issue .sb-h{color:#7A4806}
.sb-issue-line{font-size:24px;line-height:1.45;margin:0;word-break:keep-all}
.sb-issue-line b{color:#8A5207}

.sb-ask{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:16px;flex:1;min-height:0}
.sb-ask-hero{background:var(--sb-ask);color:#fff;border-radius:6px;padding:34px 38px;display:flex;flex-direction:column;justify-content:center;gap:14px}
.sb-ask-kicker{margin:0;font-size:20px;font-weight:700;opacity:.9}
.sb-ask-amount{margin:0;font-size:84px;font-weight:800;letter-spacing:-.04em;line-height:1;font-variant-numeric:tabular-nums}
.sb-ask-amount span{font-size:28px;margin-left:8px;font-weight:700}
.sb-ask-what{margin:0;font-size:26px}
.sb-ask-why{margin:0;font-size:17px;opacity:.92;border-top:1px solid #ffffff66;padding-top:14px}
.sb-ask-side{display:grid;grid-template-rows:auto minmax(0,1fr);gap:14px;min-height:0}
.sb-list{margin:0;padding-left:20px;font-size:19px;line-height:1.7}
.reveal-spotlight .sb-ask-hero.focus{box-shadow:0 0 0 3px #7A4806}

.sb-dept{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:14px;flex:1;min-height:0}
.sb-defs th[scope=row]{white-space:nowrap}
.sb-defs td,.sb-defs th{font-size:18px;padding-top:13px;padding-bottom:13px}

.focus .sb-shrink,.sb-shrink-cover{transform-box:fill-box;transform-origin:left center;animation:sb-shrink 1.1s cubic-bezier(.3,.7,.2,1) .2s both}
.focus .sb-late{animation:sb-fade .5s 1.2s both}
.focus .sb-dot{animation:sb-pop .35s calc(var(--d) * 1ms) both}
.focus .sb-cell{animation:sb-pop .3s calc(var(--d) * 1ms) both}
.focus .sb-line{stroke-dasharray:1;animation:sb-draw 1s ease-out both}
.focus .sb-planes{animation:sb-fade .6s .2s both}
.focus .sb-grow{transform-box:fill-box;transform-origin:left center;animation:sb-shrink .9s ease-out .3s both}
@keyframes sb-shrink{from{transform:scaleX(var(--from,1.6))}to{transform:none}}
@keyframes sb-fade{from{opacity:0}to{opacity:1}}
@keyframes sb-pop{from{opacity:0}to{opacity:1}}
@keyframes sb-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@media (prefers-reduced-motion: reduce){.sb-shrink,.sb-shrink-cover,.sb-late,.sb-dot,.sb-cell,.sb-line,.sb-planes,.sb-grow{animation:none!important}}
